@import "@fontsource-variable/manrope";
@import "@fontsource-variable/jetbrains-mono";

/* Light sibling: an off-white page (#eaecee) with navy text, white strips, navy tiles
   (secondary) that hover to a lighter navy, the same orange a shade deeper for contrast. */
:root {
  --background: oklch(0.942 0.003 248);
  --foreground: oklch(0.318 0.103 258);
  --card: oklch(0.99 0.005 258);
  --card-foreground: oklch(0.318 0.103 258);
  --popover: oklch(0.99 0.005 258);
  --popover-foreground: oklch(0.318 0.103 258);
  --primary: oklch(0.635 0.15 51);
  --primary-foreground: oklch(0.318 0.103 258);
  --secondary: oklch(0.318 0.103 258);
  --secondary-foreground: oklch(0.942 0.003 248);
  --muted: oklch(0.868 0.009 248);
  --muted-foreground: oklch(0.509 0.077 257);
  --accent: oklch(0.398 0.112 257);
  --accent-foreground: oklch(0.99 0.005 258);
  --destructive: oklch(0.58 0.2 27);
  --destructive-foreground: oklch(0.99 0.005 258);
  --border: oklch(0.722 0.053 257);
  --input: oklch(0.722 0.053 257);
  --ring: oklch(0.635 0.15 51);
  --highlight: oklch(0.702 0.149 52);
  --highlight-foreground: oklch(0.318 0.103 258);
  --glow: oklch(0.702 0.149 52);
  --chart-1: oklch(0.635 0.15 51);
  --chart-2: oklch(0.318 0.103 258);
  --chart-3: oklch(0.509 0.077 257);
  --chart-4: oklch(0.722 0.053 257);
  --chart-5: oklch(0.641 0.022 260);
  --sidebar: oklch(0.99 0.005 258);
  --sidebar-foreground: oklch(0.318 0.103 258);
  --sidebar-primary: oklch(0.635 0.15 51);
  --sidebar-primary-foreground: oklch(0.318 0.103 258);
  --sidebar-accent: oklch(0.868 0.009 248);
  --sidebar-accent-foreground: oklch(0.318 0.103 258);
  --sidebar-border: oklch(0.722 0.053 257);
  --sidebar-ring: oklch(0.635 0.15 51);

  --typeface-body: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Manrope Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "JetBrains Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 120rem;
  --page-gutter: clamp(1rem, 0.8rem + 0.55vw, 1.5rem);
  --section-y: 2.625rem;
}

/* Dark (faithful): the navy page #0a3065, off-white #eaecee text and light tiles that hover
   to #cfd4d9, orange #e6813b headlines and tiles, #1a4682 hover on navy, #fafcff strip,
   #90a7c7 labels, #496792 hairlines. */
.dark {
  --background: oklch(0.318 0.103 258);
  --foreground: oklch(0.942 0.003 248);
  --card: oklch(0.99 0.005 258);
  --card-foreground: oklch(0.318 0.103 258);
  --popover: oklch(0.398 0.112 257);
  --popover-foreground: oklch(0.99 0.005 258);
  --primary: oklch(0.702 0.149 52);
  --primary-foreground: oklch(0.318 0.103 258);
  --secondary: oklch(0.942 0.003 248);
  --secondary-foreground: oklch(0.318 0.103 258);
  --muted: oklch(0.398 0.112 257);
  --muted-foreground: oklch(0.722 0.053 257);
  --accent: oklch(0.868 0.009 248);
  --accent-foreground: oklch(0.318 0.103 258);
  --destructive: oklch(0.65 0.2 27);
  --destructive-foreground: oklch(0.99 0.005 258);
  --border: oklch(0.509 0.077 257);
  --input: oklch(0.509 0.077 257);
  --ring: oklch(0.702 0.149 52);
  --highlight: oklch(0.635 0.15 51);
  --highlight-foreground: oklch(0.318 0.103 258);
  --glow: oklch(0.702 0.149 52);
  --chart-1: oklch(0.702 0.149 52);
  --chart-2: oklch(0.942 0.003 248);
  --chart-3: oklch(0.722 0.053 257);
  --chart-4: oklch(0.509 0.077 257);
  --chart-5: oklch(0.635 0.15 51);
  --sidebar: oklch(0.29 0.095 258);
  --sidebar-foreground: oklch(0.942 0.003 248);
  --sidebar-primary: oklch(0.702 0.149 52);
  --sidebar-primary-foreground: oklch(0.318 0.103 258);
  --sidebar-accent: oklch(0.398 0.112 257);
  --sidebar-accent-foreground: oklch(0.99 0.005 258);
  --sidebar-border: oklch(0.509 0.077 257);
  --sidebar-ring: oklch(0.702 0.149 52);
}
